import { supabase } from '../../../services/supabase';

export interface Job {
    id: string; // The UUID
    job_id: string; // The "Sr. No" like 3543645757 from the design
    job_type: string;
    job_title: string;
    posted_by: {
        name: string;
        avatar_url?: string;
    };
    status: string;
    received_proposals: number;
    posted_date: string;
}

export const fetchJobs = async (): Promise<Job[]> => {
    const { data, error } = await supabase
        .from('jobs')
        .select(`
      id,
      title,
      job_location_type,
      posted_by_user_name,
      status,
      applicants,
      posted_at
    `)
        .order('posted_at', { ascending: false });

    if (error) {
        console.error('Error fetching jobs:', error);
        return [];
    }

    return (data || []).map((row: any) => {
        // Generate a short ID from the UUID for the table
        const shortId = typeof row.id === 'string' ? row.id.split('-')[0].toUpperCase() : '';

        // Format date beautifully
        const d = new Date(row.posted_at);
        const dateStr = !isNaN(d.getTime())
            ? d.toLocaleDateString('en-GB') // DD/MM/YYYY format
            : row.posted_at;

        return {
            id: row.id,
            job_id: shortId,
            job_type: row.job_location_type || 'Full Time',
            job_title: row.title || 'Untitled Job',
            posted_by: {
                name: row.posted_by_user_name || 'Anonymous',
            },
            status: typeof row.status === 'string'
                ? row.status.charAt(0).toUpperCase() + row.status.slice(1).replace(/_/g, ' ')
                : 'Pending',
            received_proposals: row.applicants || 0,
            posted_date: dateStr,
        };
    });
};
